fn not_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // We assume `a.len() == b.len()`.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x != y)
     .collect()
}

